/**
 * 临时窄屏验证脚本：复用 home-v2 mocks，走 nginx 部署站点（8101），
 * 在窄视口下截取「区域栏 + 日期」与「带 tab 的卡片头」两张图，验证：
 * 1) 图1：区域 tab 与日期不再重叠，日期完整显示，超出在区域内横向滚动
 * 2) 图2：卡片标题完整不换行，分段 tab 横向滚动不撑破
 */
import { chromium } from 'playwright'
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import {
  mockBenefitData,
  mockCheckData,
  mockGetInfo,
  mockKeyData,
  mockDeptTreeInPermission,
  mockRepairData,
  mockRouters,
  mockSunshineData,
  mockStudyList,
  mockTaskCount,
  mockTodoList
} from './home-v2-mocks.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const OUT = path.join(__dirname, 'screenshots')
if (!fs.existsSync(OUT)) fs.mkdirSync(OUT, { recursive: true })

const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8101'
const API_PREFIX = '/api/v2.0'

function jsonResponse(body) {
  return { status: 200, contentType: 'application/json', body: JSON.stringify(body) }
}

async function main() {
  const browser = await chromium.launch({ headless: true })
  const context = await browser.newContext({ viewport: { width: 900, height: 1400 }, deviceScaleFactor: 1 })

  await context.route(`**${API_PREFIX}/**`, async (route) => {
    const url = route.request().url()
    const pathname = url.split(API_PREFIX)[1] || ''
    if (pathname.includes('/system/platformConfig/getInfo')) return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: { region: '320500', platformName: '苏住房智慧物业管理平台' } }))
    if (pathname.includes('/getInfo')) return route.fulfill(jsonResponse(mockGetInfo))
    if (pathname.includes('/system/dept/treeInPermission')) return route.fulfill(jsonResponse(mockDeptTreeInPermission))
    if (pathname.includes('/menu/listRouters')) return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: mockRouters }))
    if (pathname.includes('/portal/home/keyData') || pathname.includes('/getKeyData')) return route.fulfill(jsonResponse(mockKeyData))
    if (pathname.includes('/portal/home/checkData') || pathname.includes('/getCheckData')) return route.fulfill(jsonResponse(mockCheckData))
    if (pathname.includes('/portal/home/benefitData') || pathname.includes('/getBenefitData')) return route.fulfill(jsonResponse(mockBenefitData))
    if (pathname.includes('/portal/home/taskCount') || pathname.includes('/task/taskCount')) return route.fulfill(jsonResponse(mockTaskCount))
    if (pathname.includes('/portal/home/repairData') || pathname.includes('/getRepairData')) return route.fulfill(jsonResponse(mockRepairData))
    if (pathname.includes('/portal/home/sunshineData') || pathname.includes('/statistics/overview')) return route.fulfill(jsonResponse(mockSunshineData))
    if (pathname.includes('/businessNotice/page')) return route.fulfill(jsonResponse(mockStudyList.businessNotice))
    if (pathname.includes('/richText/page')) return route.fulfill(jsonResponse(mockStudyList.richText))
    if (pathname.includes('/video/page')) return route.fulfill(jsonResponse(mockStudyList.video))
    if (pathname.includes('/problem/page')) return route.fulfill(jsonResponse(mockStudyList.problem))
    if (pathname.includes('/todoTaskList')) return route.fulfill(jsonResponse(mockTodoList))
    if (pathname.includes('/secret/key')) return route.fulfill(jsonResponse({ code: 500, msg: 'skip sign' }))
    return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: [], rows: [], total: 0 }))
  })

  await context.addInitScript(() => {
    try {
      const orig = sessionStorage.getItem.bind(sessionStorage)
      Object.defineProperty(sessionStorage, 'getItem', {
        configurable: true,
        value: function (key) { return key === 'Admin-Token' ? 'e2e-mock-token' : orig(key) }
      })
      localStorage.setItem('layout-setting', JSON.stringify({ topNav: true, tagsView: true, fixedHeader: true, sidebarLogo: true }))
    } catch (e) {}
  })

  const page = await context.newPage()
  await page.goto(`${BASE_URL}/#/index`, { waitUntil: 'domcontentloaded', timeout: 120000 })
  await page.waitForSelector('.home-v2', { timeout: 60000 })
  await page.waitForTimeout(1200)

  // 图1：区域栏 + 日期
  const region = await page.locator('.home-v2__region').first()
  await region.screenshot({ path: path.join(OUT, 'narrow-region.png') })

  // 图2：第二行卡片头（公共收益 / 双晒公示 / 马上办，含 SegTabs）
  const row2 = page.locator('.home-v2__row--2').first()
  await row2.screenshot({ path: path.join(OUT, 'narrow-row2.png') })

  // 断言：日期与区域 tab 不重叠（日期左边界 >= 区域tab右边界）
  const overlap = await page.evaluate(() => {
    const period = document.querySelector('.home-v2__period')
    const tabs = document.querySelector('.home-v2__region-tabs')
    if (!period || !tabs) return { ok: false, reason: 'missing el' }
    const p = period.getBoundingClientRect()
    const t = tabs.getBoundingClientRect()
    const periodFullyVisible = period.scrollWidth <= period.clientWidth + 1
    return {
      ok: t.right <= p.left + 1,
      tabsRight: Math.round(t.right),
      periodLeft: Math.round(p.left),
      periodRight: Math.round(p.right),
      viewport: window.innerWidth,
      periodFullyVisible,
      periodText: period.textContent.trim()
    }
  })

  // 断言：卡片标题不换行（sc__title 高度约 20，不超过 24），tab 容器可滚动
  const header = await page.evaluate(() => {
    const out = []
    document.querySelectorAll('.home-v2__row--2 .sc').forEach((sc) => {
      const title = sc.querySelector('.sc__title')
      const hdR = sc.querySelector('.sc__hd-r')
      const seg = sc.querySelector('.seg')
      if (!title) return
      const tr = title.getBoundingClientRect()
      out.push({
        title: title.textContent.trim(),
        titleH: Math.round(tr.height),
        titleLines: Math.round(tr.height / 20),
        segScrollable: seg ? seg.scrollWidth > seg.clientWidth : null,
        hdROverflowScroll: hdR ? hdR.scrollWidth > hdR.clientWidth : null
      })
    })
    return out
  })

  console.log('OVERLAP_CHECK>', JSON.stringify(overlap, null, 2))
  console.log('HEADER_CHECK>', JSON.stringify(header, null, 2))

  await browser.close()
}

main().catch((e) => { console.error(e); process.exit(1) })

